const visual = {
  prepare: function (input) { return []; },
  render: function (input, metrics) {
    var w = input.viewport.widthDu, h = input.viewport.heightDu;
    var cols = 4, rows = 6;
    var margin = Math.min(w, h) * 0.08;
    var cell = Math.min((w - margin * 2) / cols, (h - margin * 2) / rows);
    var gw = cell * cols, gh = cell * rows;
    var x0 = (w - gw) / 2, y0 = (h - gh) / 2;
    var paths = [], children = [];
    var i, j;
    for (i = 0; i <= cols; i++) {
      paths.push({ id: 'v' + i, commands: visualSdk.polyline([[x0 + i * cell, y0], [x0 + i * cell, y0 + gh]]) });
      children.push({ type: 'path', pathId: 'v' + i, stroke: '#26354a', strokeWidth: 1.5 });
    }
    for (j = 0; j <= rows; j++) {
      paths.push({ id: 'h' + j, commands: visualSdk.polyline([[x0, y0 + j * cell], [x0 + gw, y0 + j * cell]]) });
      children.push({ type: 'path', pathId: 'h' + j, stroke: '#26354a', strokeWidth: 1.5 });
    }
    return {
      schemaVersion: 1,
      sceneId: 'squareGrid',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
